// ==================== INITIALIZATION ====================
document.addEventListener('DOMContentLoaded', async () => {
    await loadAllData();
    loadFacilityRooms(); // Load rooms from Facility Management portal
    initializeSemester(); // Initialize semester management
    loadSavedAllocation(); // Load allocation for current semester
    initializeEventListeners();
    
    // Stay logged in after a page refresh (session cookie checked by the server)
    try {
        const session = await window.api.me();
        if (session && session.role) {
            if (session.redirect) { window.location.href = session.redirect; return; }  // staff portal user
            await startSession(session.role, session.user);
        } else if (/login=required/.test(location.search)) {
            showToast('Please log in to open that page.', 'info');
        }
    } catch (err) {
        console.log('Session check failed:', err.message);
    }
    
    console.log('CCK SIS v2 initialized - Semester:', AppState.currentSemester);
});

// Load saved allocation from localStorage
function loadSavedAllocation() {
    try {
        const semester = AppState.currentSemester || 'spring2026';
        const saved = localStorage.getItem('cck_saved_allocation_' + semester);
        if (saved) {
            AppState.savedAllocation = JSON.parse(saved);
            window.lastAllocationResults = AppState.savedAllocation;
            console.log('Loaded saved allocation for', semester + ':', AppState.savedAllocation.results?.length, 'courses');
        } else {
            AppState.savedAllocation = null;
            window.lastAllocationResults = null;
        }
    } catch (e) {
        console.log('No saved allocation found');
    }
}

// Save allocation to localStorage and AppState
function saveAllocation(allocationResults) {
    const semester = AppState.currentSemester || 'spring2026';
    const semesterLabel = getSemesterLabel(semester);
    
    AppState.savedAllocation = {
        ...allocationResults,
        savedAt: new Date().toISOString(),
        semester: semesterLabel,
        semesterKey: semester
    };
    localStorage.setItem('cck_saved_allocation_' + semester, JSON.stringify(AppState.savedAllocation));
    window.lastAllocationResults = AppState.savedAllocation;
    console.log('Allocation saved for', semesterLabel + ':', allocationResults.results?.length, 'courses');
    
    // Save to Supabase database
    if (typeof saveAllocationToDatabase === 'function') {
        saveAllocationToDatabase(allocationResults);
    }
}

// ==================== SEMESTER MANAGEMENT ====================

// Get semester label from key
function getSemesterLabel(semesterKey) {
    const labels = {
        'fall2026': 'Fall 2026',
        'spring2026': 'Spring 2026',
        'fall2025': 'Fall 2025',
        'spring2025': 'Spring 2025',
        'fall2024': 'Fall 2024',
        'spring2024': 'Spring 2024'
    };
    return labels[semesterKey] || semesterKey;
}

// Change semester - called from dropdown - AFFECTS ENTIRE WEBSITE
window.changeSemester = function(semesterKey) {
    console.log('=== CHANGING SEMESTER TO:', semesterKey, '===');
    
    // Save current semester's data before switching
    saveSemesterData(AppState.currentSemester);
    
    // Update current semester globally
    AppState.currentSemester = semesterKey;
    localStorage.setItem('cck_current_semester', semesterKey);
    
    // Update SemesterData object for analytics
    if (typeof SemesterData !== 'undefined') {
        SemesterData.currentSemester = semesterKey;
    }
    
    // Sync with database if connected
    if (typeof saveCurrentSemesterToDB === 'function') {
        saveCurrentSemesterToDB(semesterKey);
    }
    if (typeof setSemesterContext === 'function') {
        setSemesterContext(semesterKey);
    }
    
    // Load data for the new semester
    loadSemesterData(semesterKey);
    
    // Update ALL semester dropdowns on the page
    updateAllSemesterDropdowns(semesterKey);
    
    // Update page title/subtitle to show semester
    updatePageHeaderForSemester(semesterKey);
    
    // Refresh the current view with new semester data
    refreshCurrentView();
    
    showToast('Switched to ' + getSemesterLabel(semesterKey), 'success');
};

// Update all semester dropdowns across the page
function updateAllSemesterDropdowns(semesterKey) {
    // Main header dropdown
    const mainDropdown = document.getElementById('semester-select');
    if (mainDropdown) {
        mainDropdown.value = semesterKey;
    }
    
    // Timetable semester dropdown
    const timetableDropdown = document.getElementById('timetable-semester');
    if (timetableDropdown) {
        // Convert key to label format
        const label = getSemesterLabel(semesterKey);
        for (let option of timetableDropdown.options) {
            if (option.value === label || option.text === label) {
                timetableDropdown.value = option.value;
                break;
            }
        }
    }
    
    // Analytics semester dropdown
    const analyticsDropdown = document.getElementById('analytics-semester-filter');
    if (analyticsDropdown) {
        analyticsDropdown.value = semesterKey;
    }
}

// Update page header to show current semester
function updatePageHeaderForSemester(semesterKey) {
    const subtitle = document.getElementById('admin-page-subtitle');
    if (subtitle) {
        subtitle.textContent = 'Canadian College of Kuwait • ' + getSemesterLabel(semesterKey);
    }
}

// Save current semester's data to localStorage and database
function saveSemesterData(semesterKey) {
    if (!semesterKey) return;
    
    const data = {
        allocation: AppState.savedAllocation,
        timetables: localStorage.getItem('cck_timetables_' + semesterKey),
        advising: localStorage.getItem('cck_advising_' + semesterKey),
        savedAt: new Date().toISOString()
    };
    
    localStorage.setItem('cck_semester_data_' + semesterKey, JSON.stringify(data));
    console.log('Saved semester data for', semesterKey);
    
    // Also save analytics snapshot to database
    if (typeof saveAnalyticsSnapshot === 'function') {
        saveAnalyticsSnapshot(semesterKey);
    }
}

// Load semester data from localStorage and database
function loadSemesterData(semesterKey) {
    // Load allocation for this semester
    loadSavedAllocation();
    
    // Try to load from database first
    if (typeof loadAllocationFromDatabase === 'function') {
        loadAllocationFromDatabase(semesterKey).then(result => {
            if (result.success && result.data) {
                AppState.savedAllocation = result.data;
                window.lastAllocationResults = result.data;
                console.log('Loaded allocation from', result.source, 'for', semesterKey);
            }
        });
    }
    
    // Load timetables for this semester
    const timetableKey = 'cck_timetables_' + semesterKey;
    const savedTimetables = localStorage.getItem(timetableKey);
    if (savedTimetables) {
        try {
            AppState.semesterData[semesterKey] = AppState.semesterData[semesterKey] || {};
            AppState.semesterData[semesterKey].timetables = JSON.parse(savedTimetables);
        } catch (e) {
            console.log('No timetables for', semesterKey);
        }
    }
    
    console.log('Loaded semester data for', semesterKey);
}

// Save timetable for current semester
function saveTimetableForSemester(program, timetableData) {
    const semester = AppState.currentSemester || 'spring2026';
    const key = 'cck_timetables_' + semester;
    
    let timetables = {};
    try {
        const saved = localStorage.getItem(key);
        if (saved) timetables = JSON.parse(saved);
    } catch (e) {}
    
    timetables[program] = {
        data: timetableData,
        savedAt: new Date().toISOString(),
        semester: getSemesterLabel(semester)
    };
    
    localStorage.setItem(key, JSON.stringify(timetables));
    console.log('Saved timetable for', program, 'in', semester);
}

// Get timetable for current semester
function getTimetableForSemester(program) {
    const semester = AppState.currentSemester || 'spring2026';
    const key = 'cck_timetables_' + semester;
    
    try {
        const saved = localStorage.getItem(key);
        if (saved) {
            const timetables = JSON.parse(saved);
            return timetables[program] || null;
        }
    } catch (e) {}
    
    return null;
}

// Refresh the current view after semester change
function refreshCurrentView() {
    // Find which section is currently active
    const activeSection = document.querySelector('.admin-section.active');
    if (!activeSection) return;
    
    const sectionId = activeSection.id;
    
    switch(sectionId) {
        case 'section-dashboard':
            loadAdminDashboard();
            break;
        case 'section-students':
            loadStudentManagement();
            break;
        case 'section-allocation':
            loadCourseAllocation();
            break;
        case 'section-instructors':
            loadInstructorManagement();
            break;
        case 'section-timetable':
            loadTimetableGeneration();
            break;
        case 'section-analytics':
            loadAnalytics();
            break;
        case 'section-predictions':
            if (typeof loadPredictions === 'function') loadPredictions();
            break;
        case 'section-advising':
            if (typeof loadCourseAdvising === 'function') loadCourseAdvising();
            break;
    }
}

// Initialize semester on page load
function initializeSemester() {
    // Load saved semester preference
    const savedSemester = localStorage.getItem('cck_current_semester');
    if (savedSemester) {
        AppState.currentSemester = savedSemester;
    } else {
        AppState.currentSemester = 'spring2026'; // Default
    }
    
    // Update dropdown
    const dropdown = document.getElementById('semester-select');
    if (dropdown) {
        dropdown.value = AppState.currentSemester;
    }
    
    // Load data for current semester
    loadSemesterData(AppState.currentSemester);
    
    console.log('Initialized semester:', AppState.currentSemester);
}

async function loadAllData() {
    try {
        // Add cache-busting timestamp to force reload of JSON files
        const cacheBust = '?v=' + Date.now() + Math.random();
        
        // Public files only. Students and enrollments are private: they come from the
        // database after login (loadPrivateData).
        const [courses, instructors, hallsSchedule, combinedCourses] = await Promise.all([
            fetch('courses.json' + cacheBust).then(r => r.json()),
            fetch('instructors.json' + cacheBust).then(r => r.json()),
            fetch('halls_schedule.json' + cacheBust).then(r => r.json()),
            fetch('combined_courses.json' + cacheBust).then(r => r.json())
        ]);
        
        // USE EMBEDDED STUDY PLANS DATA (to avoid browser caching issues)
        const studyPlans = typeof EMBEDDED_STUDY_PLANS !== 'undefined' ? EMBEDDED_STUDY_PLANS : await fetch('study_plans.json' + cacheBust).then(r => r.json());
        
        AppState.students = [];
        AppState.formerStudents = [];
        AppState.courses = courses;
        AppState.instructors = instructors;
        AppState.enrollments = [];
        AppState.studyPlans = studyPlans;
        AppState.hallsSchedule = hallsSchedule;
        AppState.combinedCourses = combinedCourses;
        
        // Process courses to add additional info
        processCoursesData();
        
        console.log(`Loaded: ${courses.length} courses (student data loads after login)`);
    } catch (error) {
        console.error('Error loading data:', error);
        showToast('Error loading data. Please refresh.', 'error');
    }
}

// Load students and enrollments from the database (needs a login).
// Admins get everything; a student gets their own record, and other students
// in the enrollment list are anonymised by the server.
async function loadPrivateData() {
    const res = await window.api.getData();
    if (res.error) {
        console.error('Could not load data:', res.error.message);
        showToast('Could not load student data: ' + res.error.message, 'error');
        return false;
    }
    // Current students drive every page and statistic; former students (graduated /
    // inactive, from the 2015-2024 records) are kept separately for Student Management.
    const all = res.data.students || [];
    const isCurrent = s => !s.status || String(s.status).toLowerCase() === 'active';
    AppState.students = all.filter(isCurrent);
    AppState.formerStudents = all.filter(s => !isCurrent(s));
    AppState.enrollments = res.data.enrollments || [];
    AppState.enrollmentSemester = res.data.enrollment_semester || 'spring2026';
    processCoursesData();
    console.log(`Loaded from database: ${AppState.students.length} students, ${AppState.enrollments.length} enrollment rows`);
    return true;
}

// Looks in current and former students
function findStudentById(studentId) {
    return AppState.students.find(s => s.student_id === studentId)
        || (AppState.formerStudents || []).find(s => s.student_id === studentId);
}

function clearPrivateData() {
    AppState.students = [];
    AppState.formerStudents = [];
    AppState.enrollments = [];
    if (typeof HistoricalData !== 'undefined') {
        HistoricalData.records = [];
        HistoricalData.courseStats = {};
        HistoricalData.studentStats = {};
        HistoricalData.loaded = false;
    }
    window.RegistrationRequests = [];
    processCoursesData();
}

// After a successful login (or a restored session): load data and open the portal
async function startSession(role, user) {
    // Pull the shared portal data (registration requests, portal submissions, rooms...)
    if (window.cckStore) window.cckStore.reload();
    try { window.RegistrationRequests = JSON.parse(localStorage.getItem('cck_registration_requests') || '[]'); } catch (e) { window.RegistrationRequests = []; }
    if (typeof loadFacilityRooms === 'function') loadFacilityRooms();
    if (typeof loadSavedAllocation === 'function') loadSavedAllocation();
    
    const ok = await loadPrivateData();
    if (!ok) return;
    
    if (typeof loadHistoricalGrades === 'function') {
        loadHistoricalGrades().then(loaded => {
            if (loaded) console.log('Historical grades loaded for predictions');
        });
    }
    
    if (role === 'admin') {
        AppState.isAdmin = true;
        AppState.currentUser = user;
        if (typeof initializeDatabase === 'function') initializeDatabase();
        showAdminPortal();
    } else {
        // Use the record from the loaded data so edits stay in sync
        AppState.isAdmin = false;
        AppState.currentUser = AppState.students.find(s => s.student_id === user.student_id) || user;
        showStudentPortal();
    }
}

// Helper function to convert Supabase student to app format
function convertSupabaseStudent(s) {
    // Try to get original_data from metadata if available
    let originalData = {};
    if (s.metadata) {
        try {
            const meta = typeof s.metadata === 'string' ? JSON.parse(s.metadata) : s.metadata;
            if (meta.original_data) {
                originalData = meta.original_data;
            }
        } catch (e) {}
    }
    
    // Calculate level from entry_year or use existing level
    let level = s.level;
    if (!level || level === 'Unknown') {
        level = calculateLevelFromEntryYear(s.entry_year, s.student_id);
    } else {
        level = convertLevelToText(level);
    }
    
    // Get metadata values
    let metadata = {};
    if (s.metadata) {
        try {
            metadata = typeof s.metadata === 'string' ? JSON.parse(s.metadata) : s.metadata;
        } catch (e) {}
    }
    
    return {
        student_id: s.student_id,
        name: s.name || originalData.name || '',
        name_ar: originalData.name_ar || metadata.name_ar || '',
        civil_id: s.civil_id || originalData.civil_id || metadata.civil_id || '',
        email: s.email || originalData.email || '',
        phone: originalData.phone || metadata.phone || '',
        gender: s.gender || originalData.gender || metadata.gender || '',
        major: s.major || originalData.major || '',
        level: level,
        gpa: parseGPA(s.gpa || s.cgpa || originalData.gpa),
        enrolled_credits: originalData.enrolled_credits || 0,
        student_type: originalData.student_type || metadata.student_type || 'Normal',
        language: originalData.language || metadata.language || 'English',
        nationality: s.nationality || originalData.nationality || metadata.nationality || '',
        degree_class: originalData.degree_class || metadata.degree_class || '',
        admit_term: s.admit_term || originalData.admit_term || metadata.admit_term || '',
        entry_year: s.entry_year,
        exit_year: s.exit_year,
        status: s.status || s.enrollment_status || 'active',
        enrollment_status: s.enrollment_status || s.status || 'active'
    };
}

// Helper to parse GPA values
function parseGPA(gpa) {
    if (gpa === null || gpa === undefined || gpa === '' || gpa === 'Not Given') {
        return 'Not Given';
    }
    const num = parseFloat(gpa);
    if (isNaN(num)) return 'Not Given';
    return num;
}

// Calculate academic level from entry year
function calculateLevelFromEntryYear(entryYear, studentId) {
    const CURRENT_YEAR = 2025;
    let year = entryYear;
    
    // If no entry year, try to extract from student ID
    if (!year && studentId) {
        const idStr = String(studentId);
        if (idStr.length >= 4) {
            const yearPrefix = parseInt(idStr.substring(0, 4));
            if (yearPrefix >= 2010 && yearPrefix <= CURRENT_YEAR) {
                year = yearPrefix;
            }
        }
    }
    
    if (!year) return 'First Year';
    
    const yearsInSchool = CURRENT_YEAR - year;
    
    if (yearsInSchool <= 1) return 'First Year';
    if (yearsInSchool === 2) return 'Second Year';
    if (yearsInSchool === 3) return 'Third Year';
    return 'Fourth Year';
}

// Helper function to convert numeric level to text
function convertLevelToText(level) {
    if (!level) return 'Unknown';
    if (typeof level === 'string') return level;
    const levelMap = {
        1: 'First Year',
        2: 'Second Year',
        3: 'Third Year',
        4: 'Fourth Year',
        5: 'Fifth Year'
    };
    return levelMap[level] || `Year ${level}`;
}

function processCoursesData() {
    // Enhance course data with enrollment counts and random data for demo
    const colors = ['color-blue', 'color-green', 'color-purple', 'color-orange', 'color-yellow'];
    
    AppState.courses.forEach((course, index) => {
        // Count students, not rows: a course with a lecture and a lab has two rows per student
        const enrollmentCount = new Set(
            AppState.enrollments.filter(e => e.course_code === course.code).map(e => e.student_id)
        ).size;
        course.enrollmentCount = enrollmentCount;
        course.capacity = 35;
        course.colorClass = colors[index % colors.length];
        
        // Assign random room for demo
        const roomIndex = index % AppState.rooms.length;
        course.room = AppState.rooms[roomIndex].id;
    });
}

// ==================== EVENT LISTENERS ====================
function initializeEventListeners() {
    // Login form
    document.getElementById('login-form').addEventListener('submit', handleLogin);
    
    // Logout buttons
    document.getElementById('student-logout')?.addEventListener('click', handleLogout);
    document.getElementById('admin-logout')?.addEventListener('click', handleLogout);
    
    // Tab navigation
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.addEventListener('click', handleTabSwitch);
    });
    
    // Admin navigation
    document.querySelectorAll('.nav-link').forEach(link => {
        link.addEventListener('click', handleAdminNav);
    });
    
    // Course filters
    document.querySelectorAll('.filter-btn').forEach(btn => {
        btn.addEventListener('click', handleFilterChange);
    });
    
    // Course search
    document.getElementById('course-search')?.addEventListener('input', handleCourseSearch);
    
    // Modal close
    document.querySelector('.modal-close')?.addEventListener('click', closeModal);
    document.getElementById('modal')?.addEventListener('click', (e) => {
        if (e.target.classList.contains('modal')) closeModal();
    });
    
    // Registration buttons
    document.getElementById('save-draft')?.addEventListener('click', saveDraft);
    document.getElementById('submit-registration')?.addEventListener('click', submitRegistration);
}

// Password visibility toggle
function togglePasswordVisibility() {
    const passwordInput = document.getElementById('login-password');
    const eyeOpen = document.querySelector('.toggle-password .eye-open');
    const eyeClosed = document.querySelector('.toggle-password .eye-closed');
    
    if (passwordInput.type === 'password') {
        passwordInput.type = 'text';
        eyeOpen.style.display = 'none';
        eyeClosed.style.display = 'block';
    } else {
        passwordInput.type = 'password';
        eyeOpen.style.display = 'block';
        eyeClosed.style.display = 'none';
    }
}

// Make it globally available
window.togglePasswordVisibility = togglePasswordVisibility;

// ==================== AUTHENTICATION ====================
// Load rooms from Facility Management portal (shared via localStorage)
function loadFacilityRooms() {
    try {
        var saved = localStorage.getItem('cck_rooms_shared');
        if (saved) {
            var facilityRooms = JSON.parse(saved);
            if (facilityRooms && facilityRooms.length) {
                // Merge with AppState rooms - facility rooms take precedence
                AppState.rooms = facilityRooms.filter(function(r){
                    return r.status === 'active' || !r.status;
                }).map(function(r){
                    return {id:r.id, name:r.name, type:r.type, capacity:r.capacity, building:r.building};
                });
            }
        }
    } catch(e) {
        console.warn('Could not load facility rooms:', e);
    }
}

async function handleLogin(e) {
    e.preventDefault();
    const loginId = document.getElementById('login-id').value.trim();
    const password = document.getElementById('login-password').value.trim();
    if (!loginId || !password) {
        showToast('Enter your ID and password.', 'error');
        return;
    }
    
    const submitBtn = e.target.querySelector('button[type="submit"]');
    if (submitBtn) submitBtn.disabled = true;
    
    try {
        // The server checks every password: admin, staff portals (hod, reg1, reg2,
        // facility, nehad) and students (Student ID + Civil ID)
        const res = await window.api.login(loginId, password);
        if (res.error) {
            showToast(res.error.message || 'Login failed. Please try again.', 'error');
            return;
        }
        if (res.data.redirect) {
            // Staff portal user: open their portal page
            showToast(`Welcome to ${res.data.user.name}!`, 'success');
            setTimeout(() => { window.location.href = res.data.redirect; }, 400);
            return;
        }
        await startSession(res.data.role, res.data.user);
        if (res.data.role === 'admin') {
            showToast('Welcome, Administrator!', 'success');
        } else {
            showToast(`Welcome back, ${String(res.data.user.name || '').split(' ')[0]}!`, 'success');
        }
    } finally {
        if (submitBtn) submitBtn.disabled = false;
    }
}

async function handleLogout() {
    try { await window.api.logout(); } catch (err) { /* still log out locally */ }
    if (window.cckStore) window.cckStore.reset();
    if (typeof DatabaseState !== 'undefined') DatabaseState.isConnected = false;
    clearPrivateData();
    
    AppState.currentUser = null;
    AppState.isAdmin = false;
    AppState.selectedCourses = [];
    
    // Hide all portals, show login
    document.getElementById('login-screen').classList.add('active');
    document.getElementById('student-portal').classList.remove('active');
    document.getElementById('admin-portal').classList.remove('active');
    
    // Clear form
    document.getElementById('login-id').value = '';
    document.getElementById('login-password').value = '';
    
    showToast('You have been logged out.', 'info');
}

