                                const loadColor = inst.students >= 150 ? '#EF4444' : inst.students >= 80 ? '#F59E0B' : '#22C55E';
                                const loadBg = inst.students >= 150 ? '#FEF2F2' : inst.students >= 80 ? '#FFFBEB' : '#F0FDF4';
