function getAdvisingStats() {
    const records = window.AdvisingRecords || [];
    return {
        completed: records.filter(r => r.status === 'completed').length,
        pending: records.filter(r => r.status === 'pending').length,
        totalStudents: new Set(records.map(r => r.studentId)).size,
        totalCourses: records.reduce((sum, r) => sum + (r.selectedCourses?.length || 0), 0)
    };
}

function searchStudents(query) {
    const resultsDiv = document.getElementById('student-search-results');
    
    if (!query || query.length < 2) {
        resultsDiv.style.display = 'none';
        return;
    }
    
    const q = query.toLowerCase();
    const matches = AppState.students.filter(s => 
        s.student_id.toLowerCase().includes(q) || 
        s.name.toLowerCase().includes(q)
    ).slice(0, 8);
    
    if (matches.length === 0) {
        resultsDiv.innerHTML = '<div style="padding: 12px 16px; color: var(--gray-500); font-size: 13px;">No students found</div>';
        resultsDiv.style.display = 'block';
        return;
    }
    
    resultsDiv.innerHTML = matches.map(s => `
        <div onclick="selectStudent('${s.student_id}')" style="padding: 12px 16px; cursor: pointer; border-bottom: 1px solid var(--gray-100); display: flex; align-items: center; gap: 12px; transition: background 0.15s;"
            onmouseover="this.style.background='var(--gray-50)'" onmouseout="this.style.background='white'">
            <div style="width: 36px; height: 36px; background: var(--cck-red); border-radius: 8px; display: flex; align-items: center; justify-content: center; color: white; font-size: 12px; font-weight: 600;">
                ${s.name.split(' ').map(n => n[0]).join('').substring(0, 2)}
            </div>
            <div style="flex: 1;">
                <div style="font-size: 13px; font-weight: 600; color: var(--gray-900);">${s.name}</div>
                <div style="font-size: 11px; color: var(--gray-500);">${s.student_id} • ${s.level || 'Level 1'}</div>
            </div>
        </div>
    `).join('');
    resultsDiv.style.display = 'block';
}

function selectStudent(studentId) {
    const student = findStudentById(studentId);
    if (!student) return;
    
    // Hide search results
    document.getElementById('student-search-results').style.display = 'none';
    document.getElementById('student-search-input').value = '';
    
    // Store selected student
    document.getElementById('selected-student-id').value = studentId;
    
    // Show selected student card
    const card = document.getElementById('selected-student-card');
    card.style.display = 'block';
    document.getElementById('student-avatar').textContent = student.name.split(' ').map(n => n[0]).join('').substring(0, 2);
    document.getElementById('student-name-display').textContent = student.name;
    document.getElementById('student-id-display').textContent = studentId;
    document.getElementById('student-level-badge').textContent = student.level || 'Level 01';
    
    // Shorten major name
    let shortMajor = student.major
        .replace('Diploma of Business – ', 'Dip. ')
        .replace('Diploma of ', 'Dip. ')
        .replace('Bachelor of Business Administration (BBA) - ', 'BBA ')
        .replace('Bachelor of Business Administration (BBA) ', 'BBA ')
        .replace('Bachelor of Applied Sciences (BASc) in Computer Sciences - ', 'BASc ')
        .replace('Management and Entrepreneurship', 'Mgmt & Entr.');
    document.getElementById('student-major-display').textContent = shortMajor;
    
    // Load student courses
    loadStudentCourses(student);
}

function clearSelectedStudent() {
    document.getElementById('selected-student-card').style.display = 'none';
    document.getElementById('selected-student-id').value = '';
    document.getElementById('current-courses-list').innerHTML = '<p style="text-align: center; color: var(--gray-500); font-size: 13px; margin: 0;">Search for a student to view courses</p>';
    document.getElementById('next-courses-list').innerHTML = '<p style="text-align: center; color: var(--gray-500); font-size: 13px; margin: 0;">Search for a student to view available courses</p>';
    document.getElementById('current-course-count').textContent = '0 courses';
    document.getElementById('next-course-count').textContent = '0 courses';
    document.getElementById('selection-summary').style.display = 'none';
}

function loadStudentCourses(student) {
    // Get current enrollments
    const enrollments = AppState.enrollments.filter(e => e.student_id === student.student_id);
    
    // Render current courses
    const currentList = document.getElementById('current-courses-list');
    document.getElementById('current-course-count').textContent = `${enrollments.length} courses`;
    
    if (enrollments.length === 0) {
        currentList.innerHTML = '<p style="text-align: center; color: var(--gray-500); font-size: 13px; margin: 0;">No current enrollments</p>';
    } else {
        currentList.innerHTML = `
            <div style="display: flex; flex-direction: column; gap: 8px;">
                ${enrollments.map(e => `
                    <label style="display: flex; align-items: center; gap: 10px; padding: 10px 12px; background: white; border: 1px solid var(--gray-200); border-radius: 8px; cursor: pointer; transition: all 0.15s;"
                        onmouseover="this.style.borderColor='var(--cck-red)'" 
                        onmouseout="this.style.borderColor=this.querySelector('input').checked ? 'var(--green-400)' : 'var(--gray-200)'">
                        <input type="checkbox" name="keep-course" value="${e.course_code}" data-credits="3"
                            onchange="updateSelectionSummary(); this.parentElement.style.borderColor = this.checked ? 'var(--green-400)' : 'var(--gray-200)'; this.parentElement.style.background = this.checked ? 'var(--green-50)' : 'white';"
                            style="width: 18px; height: 18px; accent-color: var(--green-500);">
                        <div style="flex: 1; min-width: 0;">
                            <div style="font-size: 13px; font-weight: 600; color: var(--gray-900);">${e.course_code}</div>
                            <div style="font-size: 11px; color: var(--gray-500); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${e.course_name}</div>
                        </div>
                        <span style="font-size: 10px; background: var(--orange-100); color: var(--orange-600); padding: 3px 8px; border-radius: 12px; font-weight: 600;">Keep</span>
                    </label>
                `).join('')}
            </div>
        `;
    }
    
    // Get study plan and determine next semester courses
    const studyPlanKey = getStudyPlanKey(student.major);
    const studyPlan = AppState.studyPlans[studyPlanKey];
    
    // Get current semester number from level
    const levelStr = String(student.level || 'Level 01');
    const levelMatch = levelStr.match(/\d+/);
    const currentSemester = levelMatch ? parseInt(levelMatch[0]) : 1;
    const nextSemester = currentSemester + 1;
    
    // Get enrolled course codes
    const enrolledCodes = enrollments.map(e => e.course_code);
    
    // Find available courses
    let availableCourses = [];
    
    if (studyPlan && studyPlan.courses) {
        // Get courses from next semester
        availableCourses = studyPlan.courses.filter(c => {
            const semMatch = c.semester.match(/\d+/);
            const semNum = semMatch ? parseInt(semMatch[0]) : 0;
            // Include next semester courses and any remaining courses from current semester
            return (semNum === nextSemester || semNum === currentSemester) && !enrolledCodes.includes(c.code);
        }).map(c => ({
            ...c,
            isNextLevel: c.semester.includes(nextSemester.toString())
        }));
    }
    
    // Also check if we need to look at bachelor study plan for diploma students moving to bachelor
    if (availableCourses.length === 0 && currentSemester >= 4) {
        // Student might be transitioning to bachelor
        const bachelorKey = studyPlanKey.replace('DIPLOMA', 'BACHELOR');
        const bachelorPlan = AppState.studyPlans[bachelorKey];
        if (bachelorPlan && bachelorPlan.courses) {
            availableCourses = bachelorPlan.courses.filter(c => {
                const semMatch = c.semester.match(/\d+/);
                const semNum = semMatch ? parseInt(semMatch[0]) : 0;
                return semNum === 5 && !enrolledCodes.includes(c.code);
            }).map(c => ({ ...c, isNextLevel: true }));
        }
    }
    
    // Render next level courses
    const nextList = document.getElementById('next-courses-list');
    document.getElementById('next-course-count').textContent = `${availableCourses.length} courses`;
    
    if (availableCourses.length === 0) {
        nextList.innerHTML = `
            <div style="text-align: center; padding: 20px;">
                <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="var(--gray-300)" stroke-width="1.5" style="margin: 0 auto 12px;">
                    <path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>
                </svg>
                <p style="color: var(--gray-500); font-size: 13px; margin: 0;">No additional courses available</p>
                <p style="color: var(--gray-500); font-size: 11px; margin: 4px 0 0 0;">Student may have completed all requirements</p>
            </div>
        `;
    } else {
        nextList.innerHTML = `
            <div style="display: flex; flex-direction: column; gap: 8px;">
                ${availableCourses.map(c => `
                    <label style="display: flex; align-items: center; gap: 10px; padding: 10px 12px; background: white; border: 1px solid var(--gray-200); border-radius: 8px; cursor: pointer; transition: all 0.15s;"
                        onmouseover="this.style.borderColor='var(--blue-400)'" 
                        onmouseout="this.style.borderColor=this.querySelector('input').checked ? 'var(--green-400)' : 'var(--gray-200)'">
                        <input type="checkbox" name="next-course" value="${c.code}" data-credits="${c.credits || 3}"
                            onchange="updateSelectionSummary(); this.parentElement.style.borderColor = this.checked ? 'var(--green-400)' : 'var(--gray-200)'; this.parentElement.style.background = this.checked ? 'var(--green-50)' : 'white';"
                            style="width: 18px; height: 18px; accent-color: var(--green-500);">
                        <div style="flex: 1; min-width: 0;">
                            <div style="font-size: 13px; font-weight: 600; color: var(--gray-900);">${c.code}</div>
                            <div style="font-size: 11px; color: var(--gray-500); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${c.title || c.name}</div>
                        </div>
                        <div style="text-align: right;">
                            <span style="font-size: 10px; background: ${c.isNextLevel ? 'var(--blue-100)' : 'var(--purple-100)'}; color: ${c.isNextLevel ? 'var(--blue-600)' : 'var(--purple-600)'}; padding: 3px 8px; border-radius: 12px; font-weight: 600;">
                                ${c.semester}
                            </span>
                            <div style="font-size: 10px; color: var(--gray-500); margin-top: 2px;">${c.credits || 3} cr</div>
                        </div>
                    </label>
                `).join('')}
            </div>
        `;
    }
}

function updateSelectionSummary() {
    const keepCourses = document.querySelectorAll('input[name="keep-course"]:checked');
    const nextCourses = document.querySelectorAll('input[name="next-course"]:checked');
    const total = keepCourses.length + nextCourses.length;
    
    let totalCredits = 0;
    keepCourses.forEach(c => totalCredits += parseInt(c.dataset.credits) || 3);
    nextCourses.forEach(c => totalCredits += parseInt(c.dataset.credits) || 3);
    
    const summary = document.getElementById('selection-summary');
    if (total > 0) {
        summary.style.display = 'block';
        document.getElementById('total-selected').textContent = total;
        document.getElementById('credit-summary').textContent = `${totalCredits} total credits`;
    } else {
        summary.style.display = 'none';
    }
}

function submitAdvisingForm(event) {
    event.preventDefault();
    
    const studentId = document.getElementById('selected-student-id').value;
    if (!studentId) {
        showToast('Please select a student', 'error');
        return;
    }
    
    const student = findStudentById(studentId);
    const keepCourses = Array.from(document.querySelectorAll('input[name="keep-course"]:checked')).map(c => c.value);
    const nextCourses = Array.from(document.querySelectorAll('input[name="next-course"]:checked')).map(c => c.value);
    const notes = document.getElementById('advisor-notes').value;
    
    if (keepCourses.length === 0 && nextCourses.length === 0) {
        showToast('Please select at least one course', 'error');
        return;
    }
    
    // Create advising record
    const record = {
        id: Date.now(),
        studentId: studentId,
        studentName: student.name,
        major: student.major,
        level: student.level,
        keepCourses: keepCourses,
        nextCourses: nextCourses,
        selectedCourses: [...keepCourses, ...nextCourses],
        notes: notes,
        status: 'completed',
        timestamp: new Date().toISOString(),
        advisor: 'Current Advisor'
    };
    
    window.AdvisingRecords.push(record);
    
    // Update course demand
    record.selectedCourses.forEach(code => {
        if (!window.CourseDemand[code]) {
            window.CourseDemand[code] = { count: 0, students: [] };
        }
        window.CourseDemand[code].count++;
        window.CourseDemand[code].students.push(record.studentId);
    });
    
    showToast(`Advising record saved for ${student.name}`, 'success');
    
    // Refresh the page
    loadCourseAdvising();
}

function clearAdvisingForm() {
    document.getElementById('advising-form').reset();
    clearSelectedStudent();
}

function renderAdvisingRecords() {
    const records = window.AdvisingRecords || [];
    
    if (records.length === 0) {
        return `
            <div style="text-align: center; padding: 40px 20px;">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="var(--gray-300)" stroke-width="1.5" style="margin: 0 auto 12px;">
                    <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
                    <polyline points="14 2 14 8 20 8"/>
                    <line x1="16" y1="13" x2="8" y2="13"/>
                    <line x1="16" y1="17" x2="8" y2="17"/>
                </svg>
                <div style="font-size: 14px; font-weight: 500; color: var(--gray-500); margin-bottom: 4px;">No Records Yet</div>
                <div style="font-size: 12px; color: var(--gray-500);">Submit an advising session to see it here</div>
            </div>
        `;
    }
    
    return records.slice().reverse().slice(0, 5).map(record => `
        <div style="background: var(--gray-50); border-radius: 10px; padding: 14px; margin-bottom: 10px; border: 1px solid var(--gray-100);">
            <div style="display: flex; justify-content: space-between; align-items: start; margin-bottom: 10px;">
                <div style="display: flex; align-items: center; gap: 10px;">
                    <div style="width: 38px; height: 38px; background: var(--cck-red); border-radius: 10px; display: flex; align-items: center; justify-content: center; color: white; font-weight: 600; font-size: 12px;">
                        ${record.studentName.split(' ').map(n => n[0]).join('').substring(0, 2)}
                    </div>
                    <div>
                        <div style="font-size: 13px; font-weight: 600; color: var(--gray-900);">${escHtml(record.studentName)}</div>
                        <div style="font-size: 11px; color: var(--gray-500);">${record.studentId}</div>
                    </div>
                </div>
                <span style="font-size: 10px; background: var(--green-100); color: var(--green-600); padding: 4px 8px; border-radius: 12px; font-weight: 600;">
                    ${record.selectedCourses.length} courses
                </span>
            </div>
            <div style="display: flex; flex-wrap: wrap; gap: 4px;">
                ${record.selectedCourses.slice(0, 4).map(code => `
                    <span style="font-size: 10px; background: var(--blue-100); color: var(--blue-600); padding: 3px 8px; border-radius: 4px; font-weight: 500;">${code}</span>
                `).join('')}
                ${record.selectedCourses.length > 4 ? `<span style="font-size: 10px; color: var(--gray-500);">+${record.selectedCourses.length - 4}</span>` : ''}
            </div>
            <div style="font-size: 10px; color: var(--gray-500); margin-top: 8px;">
                ${new Date(record.timestamp).toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
            </div>
        </div>
    `).join('');
}

function renderDemandPreview() {
    const demand = window.CourseDemand || {};
    const entries = Object.entries(demand).sort((a, b) => b[1].count - a[1].count).slice(0, 5);
    
    if (entries.length === 0) {
        return `
            <div style="text-align: center; padding: 20px; color: var(--gray-500);">
                <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" style="margin: 0 auto 8px; opacity: 0.5;">
                    <path d="M18 20V10"/><path d="M12 20V4"/><path d="M6 20v-6"/>
                </svg>
                <p style="font-size: 12px; margin: 0;">Demand data appears after advising sessions</p>
            </div>
        `;
    }
    
    const maxDemand = entries[0]?.[1].count || 1;
    
    return `
        <div style="display: flex; flex-direction: column; gap: 10px;">
            ${entries.map(([code, data]) => `
                <div style="display: flex; align-items: center; gap: 10px;">
                    <span style="font-size: 12px; font-weight: 600; color: var(--blue-600); width: 70px;">${code}</span>
                    <div style="flex: 1; height: 8px; background: var(--gray-200); border-radius: 4px; overflow: hidden;">
                        <div style="height: 100%; width: ${(data.count/maxDemand)*100}%; background: linear-gradient(90deg, var(--cck-red), var(--orange-500)); border-radius: 4px;"></div>
                    </div>
                    <span style="font-size: 12px; font-weight: 700; color: var(--gray-700); width: 24px; text-align: right;">${data.count}</span>
                </div>
            `).join('')}
        </div>
    `;
}

function exportAdvisingRecords() {
    const records = window.AdvisingRecords || [];
    if (records.length === 0) {
        showToast('No records to export', 'error');
        return;
    }
    
    let csv = 'Student ID,Student Name,Major,Level,Courses Selected,Notes,Date,Status\n';
    records.forEach(r => {
        csv += `"${r.studentId}","${r.studentName}","${r.major}","${r.level}","${r.selectedCourses.join('; ')}","${r.notes || ''}","${new Date(r.timestamp).toLocaleDateString()}","${r.status}"\n`;
    });
    
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `advising_records_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    
    showToast('Records exported successfully', 'success');
}

// ==================== UTILITIES ====================
function showToast(message, type = 'info') {
    const container = document.getElementById('toast-container');
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    toast.innerHTML = `<span class="toast-message">${message}</span>`;
    
    container.appendChild(toast);
    
    setTimeout(() => {
        toast.style.animation = 'slideIn 0.3s ease reverse';
        setTimeout(() => toast.remove(), 300);
    }, 4000);
}

function closeModal() {
    document.getElementById('modal').classList.remove('active');
}

